cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

// Standard 3D convolution (groups = 1), NCDHW layout, square kernel.
// Cooperative tiling:
//   - blockIdx.z -> batch
//   - blockIdx.y -> tile of CcPerBlock output channels
//   - blockIdx.x -> tile of (Threads * PVec) output spatial points
// Weights for the block's output channels are staged in shared memory
// via a CuTe shared tensor; each loaded input value is reused across all
// CcPerBlock output channels held in registers.
template <typename T>
__global__ void conv3d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ B,
    T* __restrict__ Y,
    int N, int Cin, int D, int H, int Wd,
    int OC, int KD, int KH, int KW,
    int stride, int padding, int dilation,
    int Dout, int Hout, int Wout)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 16;

  const int tid = threadIdx.x;

  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int R = Cin * KD * KH * KW; // reduction size per output element

  const int P_total = Dout * Hout * Wout;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Global memory strides (int64 to avoid overflow)
  const int64_t sXn = (int64_t)Cin * D * H * Wd;
  const int64_t sXc = (int64_t)D * H * Wd;
  const int64_t sXd = (int64_t)H * Wd;
  const int64_t sXh = (int64_t)Wd;

  const int64_t sYn = (int64_t)OC * Dout * Hout * Wout;
  const int64_t sYc = (int64_t)Dout * Hout * Wout;
  const int64_t sYd = (int64_t)Hout * Wout;
  const int64_t sYh = (int64_t)Wout;

  // CuTe global tensors for this batch
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * sXn),
      make_shape(Cin, D, H, Wd),
      make_stride(sXc, sXd, sXh, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * sYn),
      make_shape(OC, Dout, Hout, Wout),
      make_stride(sYc, sYd, sYh, Int<1>{})
  );

  // Weight: [OC, Cin, KD, KH, KW] contiguous -> [OC, R]
  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(OC, R),
      make_stride((int64_t)R, Int<1>{})
  );

  // Shared memory weight tile: [CcPerBlock, R]
  extern __shared__ char smem_raw[];
  T* sW_raw = reinterpret_cast<T*>(smem_raw);
  auto sW = make_tensor(
      make_smem_ptr(sW_raw),
      make_shape(Int<CcPerBlock>{}, R),
      make_stride(R, Int<1>{})
  );

  // Stage weights for this block's output channels into shared memory
  for (int r = tid; r < R; r += Threads) {
    #pragma unroll
    for (int cc = 0; cc < CcPerBlock; ++cc) {
      int c = c_base + cc;
      sW(cc, r) = (c < OC) ? mW(c, r) : T(0);
    }
  }
  __syncthreads();

  // Precompute per-thread output point coordinates
  int  p_idx[PVec];
  int  od_arr[PVec], oh_arr[PVec], ow_arr[PVec];
  int  id0_arr[PVec], ih0_arr[PVec], iw0_arr[PVec];
  bool valid[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      int od = p / (Hout * Wout);
      int rem = p - od * (Hout * Wout);
      int oh = rem / Wout;
      int ow = rem - oh * Wout;
      od_arr[i] = od;
      oh_arr[i] = oh;
      ow_arr[i] = ow;
      id0_arr[i] = od * stride - padding;
      ih0_arr[i] = oh * stride - padding;
      iw0_arr[i] = ow * stride - padding;
      valid[i] = true;
    } else {
      od_arr[i] = oh_arr[i] = ow_arr[i] = 0;
      id0_arr[i] = ih0_arr[i] = iw0_arr[i] = 0;
      valid[i] = false;
    }
  }

  // Accumulators, initialized with bias if present
  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (B != nullptr && c < OC) bval = (float)B[c];
    #pragma unroll
    for (int i = 0; i < PVec; ++i) acc[cc][i] = bval;
  }

  // Direct convolution: loop over (Cin, KD, KH, KW)
  for (int cin = 0; cin < Cin; ++cin) {
    for (int kd = 0; kd < KD; ++kd) {
      #pragma unroll
      for (int i = 0; i < PVec; ++i) { /* bounds checked below */ }

      for (int kh = 0; kh < KH; ++kh) {
        for (int kw = 0; kw < KW; ++kw) {
          const int r = ((cin * KD + kd) * KH + kh) * KW + kw;

          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            if (!valid[i]) continue;
            int id = id0_arr[i] + kd * dilation;
            if ((unsigned)id >= (unsigned)D) continue;
            int ih = ih0_arr[i] + kh * dilation;
            if ((unsigned)ih >= (unsigned)H) continue;
            int iw = iw0_arr[i] + kw * dilation;
            if ((unsigned)iw >= (unsigned)Wd) continue;

            float xval = (float)mX(cin, id, ih, iw);

            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              acc[cc][i] += xval * (float)sW(cc, r);
            }
          }
        }
      }
    }
  }

  // Store results
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      if (!valid[i]) continue;
      mY(c, od_arr[i], oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv3d_forward(torch::Tensor x,
                             torch::Tensor w,
                             c10::optional<torch::Tensor> b,
                             int stride, int padding, int dilation) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 5, "x must be [N, Cin, D, H, W]");
  TORCH_CHECK(w.dim() == 5, "w must be [OC, Cin, KD, KH, KW] (groups=1)");

  int64_t N   = x.size(0);
  int64_t Cin = x.size(1);
  int64_t D   = x.size(2);
  int64_t H   = x.size(3);
  int64_t Wd  = x.size(4);

  int64_t OC = w.size(0);
  int64_t KD = w.size(2);
  int64_t KH = w.size(3);
  int64_t KW = w.size(4);

  TORCH_CHECK(w.size(1) == Cin, "w.size(1) must equal Cin (groups=1)");
  TORCH_CHECK(stride > 0 && dilation > 0, "stride and dilation must be > 0");
  TORCH_CHECK(padding >= 0, "padding must be >= 0");

  int64_t Dout = (D + 2 * padding - dilation * (KD - 1) - 1) / stride + 1;
  int64_t Hout = (H + 2 * padding - dilation * (KH - 1) - 1) / stride + 1;
  int64_t Wout = (Wd + 2 * padding - dilation * (KW - 1) - 1) / stride + 1;
  TORCH_CHECK(Dout > 0 && Hout > 0 && Wout > 0, "Invalid output size");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, Dout, Hout, Wout}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 16;

  const int64_t R = Cin * KD * KH * KW;
  const int64_t P_total = Dout * Hout * Wout;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((OC + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)CcPerBlock * (size_t)R * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv3d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)Cin, (int)D, (int)H, (int)Wd,
      (int)OC, (int)KD, (int)KH, (int)KW,
      (int)stride, (int)padding, (int)dilation,
      (int)Dout, (int)Hout, (int)Wout
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv3d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv3d_ext = load_inline(
    name="cute_conv3d_ext",
    cpp_sources=cpp_decl,
    cuda_sources=cuda_src,
    functions=["conv3d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Standard 3D convolution (groups=1) implemented with a single custom
    CUDA kernel written with CuTe tensors/layouts.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int,
                 stride: int = 1, padding: int = 0, dilation: int = 1,
                 groups: int = 1, bias: bool = False):
        super().__init__()
        assert groups == 1, "ModelNew supports groups=1 only"
        assert isinstance(kernel_size, int) and kernel_size >= 1
        assert stride >= 1 and padding >= 0 and dilation >= 1

        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = int(kernel_size)
        self.stride = int(stride)
        self.padding = int(padding)
        self.dilation = int(dilation)
        self.groups = int(groups)

        K = self.kernel_size
        self.weight = nn.Parameter(
            torch.empty(self.out_channels, self.in_channels, K, K, K))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv3d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            fan_in = self.in_channels * self.kernel_size ** 3
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.conv3d_forward(
            x,
            self.weight,
            self.bias if self.bias is not None else None,
            int(self.stride),
            int(self.padding),
            int(self.dilation),
        )

